-- Loka · 006: owner alerts + stricter report rules.
--
-- Applied to the live project (ksnjvgfptqhtydcmmqwm) on 21 Nov 2026 by an earlier session, but the file was
-- never committed. Copied back VERBATIM from supabase_migrations.schema_migrations on 23 Nov 2026 so the repo
-- matches the live database again. Do not edit this file; put changes in a new numbered migration.
--
-- What it does:
--  • private.owner_alerts: a feed for the owner (new / edited listing, report, new user). Nobody else can read it.
--  • guard_listing: skips nested trigger calls (pg_trigger_depth) so admin/system updates are not blocked.
--  • after_report: a listing is auto-hidden when an admin reports it, or when 3 accounts at least 3 days old
--    report it (brand-new throwaway accounts cannot gang up on a real listing).
--  • guard_report: at most 10 reports per account per 24 h; only an admin can change a report.

create table if not exists private.owner_alerts(
  id bigint generated always as identity primary key,
  kind text not null check (kind in ('new_home','new_job','edited_home','edited_job','report','new_user')),
  item uuid,
  note text not null default '' check (char_length(note) <= 160),
  created_at timestamptz not null default now(),
  seen_at timestamptz
);
create index if not exists owner_alerts_unseen on private.owner_alerts(created_at) where seen_at is null;
revoke all on private.owner_alerts from public, anon, authenticated;

create or replace function private.alert_listing() returns trigger
language plpgsql security definer set search_path = public as $$
declare k text := case tg_table_name when 'homes' then 'home' else 'job' end;
begin
  if tg_op = 'INSERT' then
    insert into private.owner_alerts(kind, item, note) values ('new_' || k, new.id, left(new.title, 120));
  elsif new.status = 'pending' and old.status is distinct from 'pending' then
    insert into private.owner_alerts(kind, item, note) values ('edited_' || k, new.id, left(new.title, 120));
  end if;
  return null;
end $$;
drop trigger if exists zz_alert_homes on public.homes;
create trigger zz_alert_homes after insert or update on public.homes for each row execute function private.alert_listing();
drop trigger if exists zz_alert_jobs on public.jobs;
create trigger zz_alert_jobs after insert or update on public.jobs for each row execute function private.alert_listing();

create or replace function private.alert_report() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into private.owner_alerts(kind, item, note) values ('report', new.item, left(new.kind || ': ' || new.why, 160));
  return null;
end $$;
drop trigger if exists zz_alert_report on public.reports;
create trigger zz_alert_report after insert on public.reports for each row execute function private.alert_report();

create or replace function private.alert_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into private.owner_alerts(kind, item) values ('new_user', new.id);
  return null;
end $$;
drop trigger if exists zz_alert_user on public.profiles;
create trigger zz_alert_user after insert on public.profiles for each row execute function private.alert_user();

revoke execute on function private.alert_listing(), private.alert_report(), private.alert_user() from public, anon, authenticated;

create or replace function public.guard_listing() returns trigger
language plpgsql security definer set search_path = public as $$
declare recent int;
begin
  if pg_trigger_depth() > 1 then
    return new;
  end if;
  if public.is_trusted() then
    new.updated_at := now();
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.owner is distinct from auth.uid() then raise exception 'you can only post as yourself'; end if;
    execute format('select count(*) from public.%I where owner = $1 and created_at > now() - interval ''24 hours''', tg_table_name)
      into recent using auth.uid();
    if recent >= 3 then raise exception 'limit: 3 new % per day', tg_table_name; end if;
    new.status := 'pending';
    new.hidden_by_reports := false;
    new.reviewed_reason := '';
    if tg_table_name = 'homes' then new.verified := false; new.verified_at := null; new.verified_checks := null; end if;
  else
    if new.owner is distinct from old.owner then raise exception 'owner cannot change'; end if;
    if new.status is distinct from old.status and new.status <> 'removed' then raise exception 'only an admin can publish'; end if;
    if new.hidden_by_reports is distinct from old.hidden_by_reports or new.reviewed_reason is distinct from old.reviewed_reason then
      raise exception 'only an admin can change review fields'; end if;
    if tg_table_name = 'homes' and (new.verified is distinct from old.verified or new.verified_at is distinct from old.verified_at
       or new.verified_checks is distinct from old.verified_checks) then raise exception 'only an admin can verify'; end if;
    if new.status <> 'removed' then new.status := 'pending'; end if;
    new.created_at := old.created_at;
  end if;
  new.updated_at := now();
  return new;
end $$;
revoke execute on function public.guard_listing() from public, anon, authenticated;

create or replace function public.after_report() returns trigger
language plpgsql security definer set search_path = public as $$
declare n int; adm boolean;
begin
  select coalesce(bool_or(p.is_admin), false),
         count(*) filter (where p.created_at <= now() - interval '3 days')
    into adm, n
    from public.reports r join public.profiles p on p.id = r.reporter
   where r.kind = new.kind and r.item = new.item and r.open;
  if adm or n >= 3 then
    execute format('update public.%I set hidden_by_reports = true where id = $1', new.kind) using new.item;
  end if;
  return new;
end $$;

create or replace function public.guard_report() returns trigger
language plpgsql security definer set search_path = public as $$
declare recent int;
begin
  if tg_op = 'INSERT' then
    if not public.is_trusted() then
      new.open := true; new.reporter := auth.uid();
      select count(*) into recent from public.reports where reporter = auth.uid() and created_at > now() - interval '24 hours';
      if recent >= 10 then raise exception 'limit: 10 reports per day'; end if;
    end if;
  elsif not public.is_trusted() then raise exception 'only an admin can change a report';
  end if;
  return new;
end $$;
revoke execute on function public.after_report(), public.guard_report() from public, anon, authenticated;
